const assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),path=require('node:path');
class Element{constructor(tag,text){this.tag=tag;this.textContent=text||'';this.children=[];this.listeners={};this.disabled=false;this.value='';}append(...v){this.children.push(...v);}replaceChildren(...v){this.children=v;}addEventListener(k,f){this.listeners[k]=f;}setAttribute(){}}
const host=new Element('section'),requests=[],scope={organization_id:'org',cluster_id:'cluster',application_id:'app'};
let caps=['investigate'],expiry=Date.now()+60000;
const ctx={console,Date,URLSearchParams,generation:1,$:()=>host,node:(tag,text)=>new Element(tag,text),scopeQuery:s=>new URLSearchParams(s).toString(),status:()=>{},api:async(url,opts)=>{if(opts){requests.push({url,body:JSON.parse(opts.body)});return {}}if(url.startsWith('/api/capabilities'))return caps;if(url.startsWith('/api/interactions'))return [{id:'question',incident_id:'incident',question:'IMPACT',version:1,status:'PENDING',expires_at:new Date(expiry).toISOString()}];return []}};
vm.createContext(ctx);vm.runInContext(fs.readFileSync(path.join(__dirname,'../orchestrator.js'),'utf8'),ctx);
const all=e=>[e,...e.children.flatMap(all)],button=()=>all(host).find(e=>e.tag==='button'&&e.textContent==='Submit clarification');
async function main(){await ctx.refreshInbox(scope);assert.ok(button().disabled);let select=all(host).find(e=>e.tag==='select');select.value='UNKNOWN';select.listeners.change();assert.equal(button().disabled,false);await button().listeners.click();assert.equal(requests.length,1);assert.match(requests[0].url,/\/api\/interactions\/question\/answer\?/);assert.match(requests[0].url,/application_id=app/);assert.equal(requests[0].body.version,1);assert.equal(requests[0].body.answer,'UNKNOWN');assert.equal(requests[0].body.hash,undefined);expiry=Date.now()-1000;await ctx.refreshInbox(scope);assert.equal(button(),undefined);expiry=Date.now()+60000;caps=['approve'];await ctx.refreshInbox(scope);assert.equal(button(),undefined);console.log('interaction UI contracts passed');}
main().catch(e=>{console.error(e);process.exitCode=1});
